$('mute').onclick=()=>{muted=!muted;localStream?.getAudioTracks().forEach(t=>t.enabled=!muted);$('mute').classList.toggle('active',muted);$('muteLabel').textContent=muted?'Mikrofonu aç':'Mikrofonu kapat';send({type:'mute',muted});const c=document.getElementById(`person-${myId}`);if(c){c.querySelector('.person-meta').textContent=muted?'Mikrofon kapalı':'Bu cihaz';c.querySelector('.person-mic').textContent=muted?'⊘':'♩'}};
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Kopyalandı, arkadaşlarınla paylaşabilirsin.')}catch{toast(`Oda kodu: ${roomCode}`)}}
$('copy').onclick=()=>copy(`${location.origin}/?room=${roomCode}`);$('copyCode').onclick=()=>copy(roomCode);
$('voiceDockLeave').onclick=()=>{$('leave').click()};$('leave').onclick=()=>{$('voiceDock').classList.add('hidden');stopLive(true);socket?.close();connections.forEach(pc=>pc.close());connections.clear();localStream?.getTracks().forEach(t=>t.stop());localStream=null;activeVoiceChannel=null;document.querySelectorAll('audio[id^="audio-"]').forEach(a=>a.remove());roomView.classList.add('hidden');$('communityApp').classList.remove('hidden');renderChannels();muted=false;$('mute').classList.remove('active');$('muteLabel').textContent='Mikrofonu kapat'};
function showCommunityModal(mode){modalMode=mode;$('communityModalTitle').textContent=mode==='create'?'Topluluk oluştur':'Davet koduyla katıl';$('communityModalDescription').textContent=mode==='create'?'Arkadaşların için yeni bir alan aç.':'Arkadaşının paylaştığı topluluk kodunu gir.';$('communityModalLabel').textContent=mode==='create'?'Topluluk adı':'Davet kodu';$('communityModalInput').placeholder=mode==='create'?'ör. arkadaş grubu':'ÖRN. A1B2C3D4';$('communityModalInput').value='';$('communityModalInput').maxLength=mode==='create'?40:16;$('communityModalSubmit').textContent=mode==='create'?'Topluluk oluştur ↗':'Katıl ↗';$('switchCommunityMode').textContent=mode==='create'?'Davet kodun mu var?':'Topluluk mu oluşturacaksın?';$('communityModal').classList.remove('hidden');$('communityModalInput').focus()}
function showActionModal(mode,initialType='text',initialCategory=''){actionMode=mode;const isFriend=mode==='friend';$('actionModalTitle').textContent=isFriend?'Arkadaş ekle':'Kanal oluştur';$('actionModalDescription').textContent=isFriend?'Arkadaşının kullanıcı adını yaz.':'Topluluğunda yeni bir alan aç.';$('actionModalLabel').textContent=isFriend?'Kullanıcı adı':'Kanal adı';$('actionModalInput').placeholder=isFriend?'ör. deniz_24':'ör. oyun-sohbeti';$('actionModalInput').maxLength=isFriend?20:32;$('actionModalInput').pattern=isFriend?'[A-Za-z0-9_-]{3,20}':'';$('channelTypeRow').classList.toggle('hidden',isFriend);$('channelCategoryRow').classList.toggle('hidden',isFriend);$('channelType').value=initialType;$('channelCategory').value=initialCategory;$('actionModalSubmit').textContent=isFriend?'İstek gönder ↗':'Kanal oluştur ↗';$('actionModal').classList.remove('hidden');$('actionModalInput').focus()}
function renderCommunityRail(){const rail=$('communityRail');rail.replaceChildren();for(const c of communities){const b=document.createElement('button');b.className='guild-icon'+(String(c.id)===String(selectedCommunity)?' selected':'');b.title=`${c.name} · ${c.member_count} üye`;b.textContent=c.name.slice(0,2).toUpperCase();b.onclick=()=>selectCommunity(c.id);rail.append(b)}}
function toggleCommunityMenu(){document.querySelector('.community-menu')?.remove();if(communities.length<2)return;const menu=document.createElement('div');menu.className='community-menu';for(const c of communities){const button=document.createElement('button'),name=document.createElement('span'),count=document.createElement('small');button.type='button';button.className=String(c.id)===String(selectedCommunity)?'selected':'';name.textContent=c.name;count.textContent=`${c.member_count} üye`;button.append(name,count);button.onclick=()=>{menu.remove();selectCommunity(c.id)};menu.append(button)}$('communityPicker').parentElement.append(menu);const close=e=>{if(!menu.contains(e.target)&&e.target!==$('communityPicker')){menu.remove();document.removeEventListener('click',close)}};setTimeout(()=>document.addEventListener('click',close),0)}
async function loadCommunities(){try{const data=await api('/api/communities');communities=data.communities;renderCommunityRail();if(!communities.length){selectedCommunity=null;channels=[];activeChannel=null;await openFriends();return}const choice=communities.find(c=>String(c.id)===String(selectedCommunity))||communities[0];await selectCommunity(choice.id)}catch(e){toast(e.message)}}
async function selectCommunity(id,focus={}){try{const data=await api(`/api/community?id=${encodeURIComponent(id)}`);currentSpace='community';activeDM=null;selectedCommunity=String(id);channels=data.channels;const c=data.community;$('homeGuild').classList.remove('active');$('communityPicker').innerHTML=`${escapeHtml(c.name)} <span>⌄</span>`;$('sideListTitle').textContent='KANALLAR';$('memberSidebar').querySelector('.member-heading').firstChild.textContent='ÜYELER ';$('addChannel').title='Kanal ekle';$('communityNameHeader').textContent=c.name;renderCommunityRail();renderChannels();renderMembers(data.members);const chosen=focus.channelId?channels.find(x=>String(x.id)===String(focus.channelId)):activeChannel&&channels.find(x=>String(x.id)===String(activeChannel.id)&&x.type==='text');if(chosen){if(chosen.type==='voice')await joinVoiceChannel(chosen);else await selectChannel(chosen,{around:focus.around||null})}else{const first=channels.find(x=>x.type==='text');if(first)await selectChannel(first);else{$('chatMessages').innerHTML='<div class="welcome-empty"><h2>Bu toplulukta kanal yok.</h2><p>Yeni bir kanal ekleyerek başlayabilirsin.</p></div>'}}}catch(e){toast(e.message)}}
function renderChannels(){const list=$('channelList');list.replaceChildren();$('voicePeople').replaceChildren();const groups=[...new Set(channels.map(x=>String(x.category_name||'')))];if(!groups.length)groups.push('');for(const category of groups){const items=channels.filter(x=>String(x.category_name||'')===category),section=document.createElement('section'),head=document.createElement('div'),toggle=document.createElement('button'),add=document.createElement('button'),body=document.createElement('div'),key=category||'default',title=category||'KANALLAR';section.className='channel-category';const folded=localStorage.getItem(`wizzchat-folded-${key}`)==='true';head.className='channel-category-heading';toggle.type='button';toggle.className='channel-category-toggle';toggle.setAttribute('aria-expanded',String(!folded));toggle.innerHTML=`<span class="category-chevron">${folded?'›':'⌄'}</span><span>${escapeHtml(title.toLocaleUpperCase('tr-TR'))}</span>`;toggle.onclick=()=>{const collapsed=section.classList.toggle('collapsed');toggle.setAttribute('aria-expanded',String(!collapsed));toggle.querySelector('.category-chevron').textContent=collapsed?'›':'⌄';localStorage.setItem(`wizzchat-folded-${key}`,String(collapsed))};add.type='button';add.className='category-add';add.title=`${title} kategorisinde kanal oluştur`;add.textContent='＋';add.onclick=()=>showActionModal('channel','text',category);head.append(toggle,add);body.className='channel-category-items';for(const ch of items){const b=document.createElement('button'),symbol=ch.type==='voice'?'◖':'#';b.className='channel-item'+(activeChannel&&String(activeChannel.id)===String(ch.id)&&ch.type==='text'?' active':'')+(activeVoiceChannel&&String(activeVoiceChannel.id)===String(ch.id)?' active':'');b.innerHTML=`<span class="channel-symbol">${symbol}</span><span>${escapeHtml(ch.name)}</span>`;if(ch.type==='text')b.onclick=()=>selectChannel(ch);else b.onclick=()=>joinVoiceChannel(ch);body.append(b)}section.append(head,body);if(folded)section.classList.add('collapsed');list.append(section)}}
async function joinVoiceChannel(ch){activeChannel=ch;const code='V'+Number(ch.id).toString(36).toUpperCase().slice(-6);toast(`${ch.name} kanalına bağlanılıyor…`);try{await connect(code,true,ch)}catch(error){console.error('Ses kanalına bağlanılamadı:',error);toast(error?.message||'Ses kanalına girilemedi. Tekrar dene.')}}
function renderMembers(members){const list=$('memberList');list.replaceChildren();$('memberCount').textContent=String(members.length);const heading=$('memberSidebar').querySelector('.member-heading');if(!heading.querySelector('.member-close')){const close=document.createElement('button');close.type='button';close.className='member-close';close.textContent='Kapat';close.onclick=()=>$('communityApp').classList.remove('members-open');heading.append(close)}for(const m of members){const row=document.createElement('button');row.type='button';row.className='member-row member-profile-trigger';row.setAttribute('aria-label',`${m.username} profilini aç`);const av=document.createElement('div');av.className='member-avatar';paintAvatar(av,m.avatar,m.username);const info=document.createElement('div');info.className='member-info';const n=document.createElement('strong');n.textContent=m.username;const state=document.createElement('span'),dot=document.createElement('i');state.className=`member-presence presence-${m.presence_status||'online'}`;dot.setAttribute('aria-hidden','true');state.append(dot,document.createTextNode(presenceLabel(m.presence_status||'online')));const role=document.createElement('small');role.className='member-role';role.textContent=m.role==='owner'?'Topluluk sahibi':m.role==='Arkadaş'?'Arkadaş':'Topluluk üyesi';info.append(n,state,role);if(m.bio){const bio=document.createElement('small');bio.className='member-bio';bio.textContent=m.bio;info.append(bio)}row.append(av,info);row.onclick=()=>showMemberProfile(m);list.append(row)}}
function showMemberProfile(member){const modal=$('memberProfileModal');paintAvatar($('memberProfileAvatar'),member.avatar,member.username);$('memberProfileName').textContent=member.username;$('memberProfileStatus').textContent=presenceLabel(member.presence_status||'online');$('memberProfileStatus').className=`member-profile-status presence-${member.presence_status||'online'}`;$('memberProfileBio').textContent=member.bio||'Bu kullanıcı henüz bio eklememiş.';$('memberProfileRole').textContent=member.role==='owner'?'Topluluk sahibi':member.role==='Arkadaş'?'Arkadaş':'Topluluk üyesi';$('memberProfileModal').classList.remove('hidden')}
function escapeHtml(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const reactionChoices=['👍','❤️','😂','🔥','🎉'];
function renderAttachments(target,attachments=[]){if(!attachments.length)return;const grid=document.createElement('div');grid.className='message-attachments';for(const file of attachments){const link=document.createElement('a');link.className=file.type.startsWith('image/')?'message-attachment image-attachment':'message-attachment file-attachment';link.href=file.data;link.download=file.name;link.setAttribute('aria-label',`${file.name} dosyasını indir`);if(file.type.startsWith('image/')){const image=document.createElement('img');image.src=file.data;image.alt=file.name;image.loading='lazy';link.append(image)}else{const icon=document.createElement('span');icon.textContent=file.type==='application/pdf'?'PDF':'TXT';const name=document.createElement('strong');name.textContent=file.name;link.append(icon,name)}grid.append(link)}target.append(grid)}
function renderPendingAttachments(){const box=$('attachmentPreview');box.replaceChildren();box.classList.toggle('hidden',!pendingAttachments.length);pendingAttachments.forEach((file,index)=>{const row=document.createElement('div');row.className='pending-attachment';const label=document.createElement('span');label.textContent=`${file.name} · ${(file.size/1024).toFixed(0)} KB`;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',`${file.name} dosyasını kaldır`);remove.onclick=()=>{pendingAttachments.splice(index,1);renderPendingAttachments()};row.append(label,remove);box.append(row)})}
function readLocalFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result,size:file.size});reader.onerror=()=>reject(new Error(`${file.name} okunamadı.`));reader.readAsDataURL(file)})}
function openComposerEmojiPicker(){document.querySelector('.composer-emoji-picker')?.remove();const picker=document.createElement('div');picker.className='composer-emoji-picker';for(const emoji of ['😀','😊','😂','❤️','👍','🔥','🎉','👀','🙏','😭','✨','🙌']){const button=document.createElement('button');button.type='button';button.textContent=emoji;button.onclick=()=>{$('messageInput').value+=emoji;$('messageInput').focus();picker.remove()};picker.append(button)}$('messageForm').append(picker)}
function paintReactions(target,messageId,reactions=[]){target.replaceChildren();for(const reaction of reactions){const pill=document.createElement('button');pill.type='button';pill.className='reaction-pill'+(reaction.mine?' active':'');pill.textContent=`${reaction.emoji} ${reaction.count}`;pill.title='Tepkiyi aç/kapat';pill.onclick=()=>toggleReaction(messageId,reaction.emoji,target);target.append(pill)}}
async function toggleReaction(messageId,emoji,target){try{const endpoint=target.dataset.messageKind==='dm'?'/api/dm-reactions':'/api/reactions';const data=await api(endpoint,'POST',{messageId,emoji});paintReactions(target,messageId,data.reactions)}catch(e){toast(e.message)}}
function openReactionPicker(messageId,button,target){document.querySelector('.emoji-picker')?.remove();const picker=document.createElement('div');picker.className='emoji-picker';for(const emoji of reactionChoices){const choice=document.createElement('button');choice.type='button';choice.textContent=emoji;choice.setAttribute('aria-label',`${emoji} tepkisi`);choice.onclick=async()=>{picker.remove();await toggleReaction(messageId,emoji,target)};picker.append(choice)}button.parentElement.append(picker);const close=e=>{if(!picker.contains(e.target)&&e.target!==button){picker.remove();document.removeEventListener('click',close)}};setTimeout(()=>document.addEventListener('click',close),0)}
function startMessageEdit(row,message){if(row.classList.contains('editing'))return;row.classList.add('editing');const content=row.querySelector('.message-content'),editor=document.createElement('div'),textarea=document.createElement('textarea'),actions=document.createElement('div'),save=document.createElement('button'),cancel=document.createElement('button');editor.className='message-editor';textarea.maxLength=4000;textarea.value=message.content;actions.className='message-edit-actions';save.type=cancel.type='button';save.textContent='Kaydet';cancel.textContent='Vazgeç';const finish=value=>{const p=document.createElement('p');p.className='message-content';p.textContent=value;editor.replaceWith(p);row.classList.remove('editing')};cancel.onclick=()=>finish(message.content);save.onclick=async()=>{const value=textarea.value.trim();if(!value)return toast('Mesaj boş olamaz.');save.disabled=true;try{const result=await api(row.dataset.messageKind==='dm'?'/api/dms':'/api/messages','PATCH',{messageId:message.id,content:value});message.content=result.message.content;message.edited_at=result.message.edited_at;finish(message.content);let marker=row.querySelector('.message-edited');if(!marker){marker=document.createElement('small');marker.className='message-edited';marker.textContent='(düzenlendi)';row.querySelector('.message-meta').append(marker)}}catch(e){save.disabled=false;toast(e.message)}};actions.append(save,cancel);editor.append(textarea,actions);content.replaceWith(editor);textarea.focus();textarea.setSelectionRange(textarea.value.length,textarea.value.length)}
function renderMessage(m,{notify=false}={}){const id=String(m.id);if(messageIds.has(id))return;messageIds.add(id);const box=$('chatMessages');box.querySelector('.welcome-empty,.channel-start')?.remove();const row=document.createElement('article');row.className='chat-message';row.id=`message-${id}`;if(currentUser&&String(m.user_id)===String(currentUser.id))row.classList.add('own-message');row.dataset.id=id;row.dataset.userId=String(m.user_id||'');row.dataset.messageKind=activeDM?'dm':'channel';const av=document.createElement('div');av.className='message-avatar';paintAvatar(av,m.avatar,m.username);const body=document.createElement('div');body.className='message-body';const head=document.createElement('div');head.className='message-meta';const who=document.createElement('strong');who.textContent=m.username;const when=document.createElement('time');when.textContent=new Date(m.created_at).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'});head.append(who,when);if(m.edited_at){const edited=document.createElement('small');edited.className='message-edited';edited.textContent='(düzenlendi)';head.append(edited)}body.append(head);if(m.content){const content=document.createElement('p');content.className='message-content';content.textContent=m.content;body.append(content)}renderAttachments(body,m.attachments||[]);const tools=document.createElement('div');tools.className='message-tools';const reactions=document.createElement('div');reactions.className='message-reactions';reactions.dataset.messageKind=row.dataset.messageKind;paintReactions(reactions,id,m.reactions||[]);const react=document.createElement('button');react.type='button';react.textContent='☺';react.title='Tepki ekle';react.setAttribute('aria-label','Tepki ekle');react.onclick=()=>openReactionPicker(id,react,reactions);tools.append(react);body.append(reactions);if(currentUser&&String(m.user_id)===String(currentUser.id)&&m.content){const edit=document.createElement('button');edit.type='button';edit.textContent='✎';edit.title='Mesajı düzenle';edit.setAttribute('aria-label','Mesajı düzenle');edit.onclick=()=>startMessageEdit(row,m);tools.append(edit)}if(tools.childElementCount)body.append(tools);row.append(av,body);box.append(row);if(notify)showIncomingNotification(m);if(/^\d+$/.test(id)&&BigInt(id)>BigInt(messageCursor||'0'))messageCursor=id}
function resetMessageView(){messageViewId++;messageLoadView=-1;messageIds.clear();messageCursor='0';messageAroundId=null;clearInterval(messagePoll);pendingAttachments=[];if($('attachmentPreview'))renderPendingAttachments()}
