$('avatarFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('PNG, JPG veya WebP fotoğraf seç.');e.target.value='';return}try{const bitmap=await createImageBitmap(file),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let encoded='';for(const quality of [.88,.78,.68,.58,.48]){encoded=canvas.toDataURL('image/webp',quality);if(encoded.length<=650000)break}if(encoded.length>650000)throw new Error('Fotoğraf küçültülemedi. Başka bir fotoğraf dene.');avatarData=encoded;profileAvatarChanged=true;paintAvatar($('profilePhotoPreview'),avatarData,currentUser.username)}catch(err){toast(err.message||'Fotoğraf açılamadı. Başka bir PNG, JPG veya WebP dene.')}finally{e.target.value=''}};
$('profileForm').onsubmit=async e=>{e.preventDefault();try{const body={username:$('profileUsername').value};if(profileAvatarChanged)body.avatar=avatarData;const result=await api('/api/profile','PATCH',body);currentUser=result.user;nameInput.value=currentUser.username;$('sidebarUsername').textContent=currentUser.username;$('sidebarStatus').textContent=presenceLabel(currentUser.presenceStatus);paintAvatar($('sidebarAvatar'),currentUser.avatar,currentUser.username);$('profileModal').classList.add('hidden');await refreshPresenceViews();toast('Profilin güncellendi.')}catch(err){toast(err.message)}};
$('settingsBio').oninput=()=>{$('settingsBioCount').textContent=`${$('settingsBio').value.length}/190`};async function refreshPresenceViews(){if(selectedCommunity){try{const data=await api(`/api/community?id=${encodeURIComponent(selectedCommunity)}`);renderMembers(data.members)}catch{}}if(currentSpace==='friends')await loadFriends()}$('settingsProfileSave').onclick=async()=>{const button=$('settingsProfileSave');button.disabled=true;try{const result=await api('/api/profile','PATCH',{username:currentUser.username,bio:$('settingsBio').value,presenceStatus:$('settingsPresenceStatus').value});currentUser=result.user;$('sidebarStatus').textContent=presenceLabel(currentUser.presenceStatus);openSettings('profile');await refreshPresenceViews();toast('Bio ve çevrimiçi durumun güncellendi.')}catch(err){toast(err.message)}finally{button.disabled=false}};
$('logout').onclick=async()=>{try{await api('/api/logout','POST',{})}catch{}socket?.close();connections.forEach(pc=>pc.close());connections.clear();localStream?.getTracks().forEach(t=>t.stop());localStream=null;$('profileModal').classList.add('hidden');showAuth();toast('Çıkış yaptın.')};
api('/api/me').then(result=>setUser(result.user)).catch(()=>showAuth());

